class VIOC_AI_FRONT_SPAWN {
	title = "VIOC: Refuerzos de la IA (infanteria y vehiculos) en el punto propio seguro mas cercano al frente";
	values[] = {0,1};
	texts[] = {"No (original)","Si"};
	default = 1;
};

//--- VIOC ai_front_spawn (agregado por tools/vio_build.py; copia configurada, no es del autor de la mision).
//--- Parametro de lobby VIOC_AI_FRONT_SPAWN: 1 = si (por defecto), 0 = todo como el original.
//--- 1) Refuerzos. La infanteria (cuarteles) y los vehiculos de tierra (fabrica ligera y pesada) que se compran para un
//---    equipo IA cuyo lider esta a mas de VIOC_FRONT_MIN_FACTORY de la fabrica aparecen en el punto propio seguro mas
//---    cercano al lider, si queda a menos de VIOC_FRONT_MAX_LEADER de el y al menos VIOC_FRONT_GAIN mas cerca que la
//---    fabrica. Puntos propios: deposito (centro), campamentos propios y puntos de aparicion de los pueblos propios
//---    (cti_town_sideID / cti_camp_sideID), FOB, estructuras y HQ. Seguro: ningun enemigo (otro bando, tambien la
//---    guerrilla) a menos de VIOC_FRONT_SAFE_RADIUS y nada de mar en linea recta entre el punto y el lider. El lugar
//---    exacto es un claro en tierra donde cabe esa clase (findEmptyPosition), sin techo encima y, si es vehiculo, plano.
//---    La tripulacion se crea ahi, como en la fabrica. Se paga lo mismo y en el mismo momento (despues del tiempo de
//---    construccion) y el limite del equipo no cambia: solo cambia el lugar. Aviones, helicopteros, barcos, camiones de
//---    rescate y lo que compran los jugadores para su propio grupo siguen saliendo de su fabrica.
//--- 2) Reaparicion. El lider IA que muere reaparece en el punto propio seguro mas cercano a donde murio, si su bando
//---    tiene un Control Center a su alcance (compra a distancia) o al grupo le quedan 2 hombres o mas. Si no, o si el
//---    equipo es aereo, como antes: estructura o HQ propio mas cercano. El comandante IA no cambia.
//--- Consola de depuracion (servidor): VIOC_FRONT_INFO = [lideres, infanteria, vehiculos, ultimo [tiempo, clase, lugar]].
VIOC_FRONT_SAFE_RADIUS = 400;	//--- ningun enemigo a menos de esto del punto (m)
VIOC_FRONT_MIN_FACTORY = 1500;	//--- refuerzos: solo si el lider esta a mas de esto de la fabrica (m)
VIOC_FRONT_MAX_LEADER = 2500;	//--- refuerzos: el punto tiene que quedar a menos de esto del lider (m)...
VIOC_FRONT_GAIN = 500;	//--- ...y al menos esto mas cerca del lider que la fabrica (m)
VIOC_FRONT_VEHICLES = 2;	//--- 0 = solo infanteria, 1 = tambien la fabrica ligera, 2 = tambien la pesada (blindados)
VIOC_FRONT_INFO = [0, 0, 0, []];

VIOC_FRONT_Enabled = {
	!((missionNamespace getVariable ["VIOC_AI_FRONT_SPAWN", 1]) isEqualTo 0)
};

//--- [lado, centro, alcance] -> puntos propios a menos de alcance del centro, del mas cercano al mas lejano.
VIOC_FRONT_Points = {
	params ["_side", "_center", "_range"];
	private _sideID = (_side) call CTI_CO_FNC_GetSideID;
	private _objs = [];
	private _keys = [];
	private _fnc_add = {
		if !(isNull _this) then {
			private _d = _this distance2D _center;
			if (_d < _range) then {_keys pushBack [_d, count _objs]; _objs pushBack _this};
		};
	};
	if !(isNil "CTI_Towns") then {
		{
			if ((_x getVariable ["cti_town_sideID", -1]) == _sideID && {(_x distance2D _center) < (_range + 1000)}) then {
				(_x) call _fnc_add;
				{ if ((_x getVariable ["cti_camp_sideID", -1]) == _sideID) then {(_x) call _fnc_add} } forEach (_x getVariable ["cti_town_camps", []]);
				{ (_x) call _fnc_add } forEach (_x getVariable ["cti_town_spawns", []]);
			};
		} forEach CTI_Towns;
	};
	{ if (alive _x) then {(_x) call _fnc_add} } forEach ((_side call CTI_CO_FNC_GetSideLogic) getVariable ["cti_fobs", []]);
	{ if (alive _x) then {(_x) call _fnc_add} } forEach ((_side) call CTI_CO_FNC_GetSideStructures);
	private _hq = (_side) call CTI_CO_FNC_GetSideHQ;
	if (!isNil "_hq" && {alive _hq}) then {(_hq) call _fnc_add};
	_keys sort true;
	_keys apply {_objs select (_x select 1)}
};

//--- [punto (el objeto si esta en el suelo, si no [x, y, 0]), lado] -> true si no hay enemigos (los otros bandos, tambien la
//--- guerrilla) a menos de VIOC_FRONT_SAFE_RADIUS. Como CTI_CO_FNC_GetHostilesInArea, pero cuenta tambien estaticas y barcos
//--- con dotacion enemiga.
VIOC_FRONT_IsSafe = {
	params ["_pos", "_side"];
	private _near = _pos nearEntities [["Man", "Car", "Motorcycle", "Tank", "Air", "Ship", "StaticWeapon"], VIOC_FRONT_SAFE_RADIUS];
	private _n = 0;
	{ _n = _n + (_x countSide _near) } forEach ([west, east, resistance] - [_side]);
	_n == 0
};

//--- [desde, hasta] -> true si la linea recta no pasa por el mar (muestra cada 100 m): nada de refuerzos en otra isla.
VIOC_FRONT_DryPath = {
	params ["_a", "_b"];
	private _n = ceil ((_a distance2D _b) / 100);
	private _dry = true;
	for "_i" from 1 to (_n - 1) do {
		if (surfaceIsWater [(_a select 0) + ((_b select 0) - (_a select 0)) * _i / _n, (_a select 1) + ((_b select 1) - (_a select 1)) * _i / _n]) exitWith {_dry = false};
	};
	_dry
};

//--- [punto, clase, es hombre] -> lugar libre en tierra cerca del punto ([x, y, 0]) o [] si no hay.
//--- findEmptyPosition con la clase real (cabe sin chocar), nada de agua, nada encima (techo) y, si es vehiculo, plano.
VIOC_FRONT_Spot = {
	params ["_anchor", "_class", "_isMan"];
	private _rmax = if (_isMan) then {30} else {60};
	private _res = [];
	for "_i" from 1 to 4 do {
		private _p = (_anchor getPos [5 + random 20, random 360]) findEmptyPosition [0, _rmax, _class];
		if (count _p > 1) then {
			_p = [_p select 0, _p select 1, 0];
			if (!(surfaceIsWater _p)
				&& {(_p distance2D _anchor) < (_rmax + 30)}
				&& {_isMan || {count (_p isFlatEmpty [-1, -1, 0.4, 4, 0, false, objNull]) > 0}}
				&& {(lineIntersectsSurfaces [(AGLToASL _p) vectorAdd [0, 0, 0.5], (AGLToASL _p) vectorAdd [0, 0, 40], objNull, objNull, false, 1, "GEOM", "NONE"]) isEqualTo []}) then {
				_res = _p;
			};
		};
		if (count _res > 0) exitWith {};
	};
	_res
};

//--- Refuerzo para un equipo IA: [clase, grupo, lado, fabrica] -> [lugar, direccion] o [] (sale en la fabrica, como antes).
VIOC_FRONT_ReinforcePos = {
	params ["_model", "_group", "_side", "_factory"];
	if !(call VIOC_FRONT_Enabled) exitWith {[]};
	if (!(_group isEqualType grpNull) || {isNull _group}) exitWith {[]};
	private _leader = leader _group;
	if (isNull _leader || {!alive _leader} || {isPlayer _leader}) exitWith {[]};
	if ((_group getVariable ["cti_nextrespawn", -1]) > time) exitWith {[]};	//--- el lider esta esperando para reaparecer
	private _isMan = _model isKindOf "Man";
	private _ftype = _factory getVariable ["cti_structure_type", ""];
	private _ok = if (_isMan) then {
		_ftype == CTI_BARRACKS
	} else {
		(_model isKindOf "LandVehicle") && {!(_model isKindOf "StaticWeapon")} && {(_ftype == CTI_LIGHT && {VIOC_FRONT_VEHICLES > 0}) || {_ftype == CTI_HEAVY && {VIOC_FRONT_VEHICLES > 1}}}
	};
	if !(_ok) exitWith {[]};
	private _lpos = getPosATL (vehicle _leader);
	_lpos = [_lpos select 0, _lpos select 1, 0];
	private _toFactory = _lpos distance2D _factory;
	if (_toFactory < VIOC_FRONT_MIN_FACTORY) exitWith {[]};
	private _res = [];
	private _checked = 0;
	{
		private _ap = getPosATL _x;
		private _ctr = if ((_ap select 2) < 5) then {_x} else {[_ap select 0, _ap select 1, 0]};
		_ap = [_ap select 0, _ap select 1, 0];
		if ([_ctr, _side] call VIOC_FRONT_IsSafe && {[_ap, _lpos] call VIOC_FRONT_DryPath}) then {
			private _spot = [_ap, _model, _isMan] call VIOC_FRONT_Spot;
			if (count _spot > 0) then {_res = [_spot, _spot getDir _lpos]};
			_checked = _checked + 1;
		};
		if (count _res > 0 || {_checked >= 5} || {_forEachIndex >= 60}) exitWith {};
	} forEach ([_side, _lpos, VIOC_FRONT_MAX_LEADER min (_toFactory - VIOC_FRONT_GAIN)] call VIOC_FRONT_Points);
	if (count _res > 0) then {
		private _i = if (_isMan) then {1} else {2};
		VIOC_FRONT_INFO set [_i, (VIOC_FRONT_INFO select _i) + 1];
		VIOC_FRONT_INFO set [3, [time, _model, +(_res select 0)]];
	};
	_res
};

//--- Reaparicion del lider IA: [lado, donde murio, grupo, unidad] -> posicion. Con el parametro en 0, o sin punto
//--- adelantado seguro, es exactamente la regla original (estructura o HQ propio mas cercano, a 8-30 m).
VIOC_FRONT_LeaderPos = {
	params ["_side", "_center", "_group", "_unit"];
	if (_side isEqualType 0) then {_side = (_side) call CTI_CO_FNC_GetSideFromID};
	private _orig = [_side, _center] call CTI_FSM_UpdateAI_GetRespawnLocation;
	private _res = [];
	if (call VIOC_FRONT_Enabled && {!isNull _group} && {!((_group getVariable ["cti_role", ""]) in (missionNamespace getVariable [format ["CTI_SQUADS_%1_KIND_AIR", _side], []]))}) then {
		private _fwd = [_side, CTI_CONTROLCENTER, _center, CTI_BASE_PURCHASE_UNITS_RANGE_CC] call CTI_CO_FNC_HasStructure;
		if !(_fwd) then {_fwd = ({alive _x} count units _group) > 2};
		if (_fwd) then {
			private _c = [_center select 0, _center select 1, 0];
			private _range = if (isNull _orig) then {100000} else {_orig distance2D _c};
			private _checked = 0;
			{
				private _ap = getPosATL _x;
				private _ctr = if ((_ap select 2) < 5) then {_x} else {[_ap select 0, _ap select 1, 0]};
				_ap = [_ap select 0, _ap select 1, 0];
				if ([_ctr, _side] call VIOC_FRONT_IsSafe && {[_ap, _c] call VIOC_FRONT_DryPath}) then {
					_res = [_ap, typeOf _unit, true] call VIOC_FRONT_Spot;
					_checked = _checked + 1;
				};
				if (count _res > 0 || {_checked >= 5} || {_forEachIndex >= 60}) exitWith {};
			} forEach ([_side, _c, _range] call VIOC_FRONT_Points);
		};
	};
	if (count _res > 0) then {
		VIOC_FRONT_INFO set [0, (VIOC_FRONT_INFO select 0) + 1];
		VIOC_FRONT_INFO set [3, [time, typeOf _unit, +_res]];
	} else {
		_res = [_orig, 8, 30] call CTI_CO_FNC_GetRandomPosition;
	};
	_res
};

//--- VIOC ai_front_spawn: si el lider de este equipo IA esta lejos de la fabrica, la unidad (infanteria o vehiculo de tierra
//--- con su tripulacion) aparece en el punto propio seguro mas cercano a el. El precio ya se cobro arriba, igual que antes;
//--- solo cambian el lugar y la direccion. Funciones en Server\Functions\FSM\Functions_FSM_UpdateAI.sqf.
if !(isNil "VIOC_FRONT_ReinforcePos") then {
	private _vioc_front = [_model, _req_target, _req_side, _factory] call VIOC_FRONT_ReinforcePos;
	if (count _vioc_front > 1) then {_position = _vioc_front select 0; _direction = (_vioc_front select 1) - getDir _factory};
};
